<section class="card"><h2>Zahlung zuordnen</h2><form method="post"><?php gszFields('allocate');estateRequest();?><label>Zahlung<select name="payment_id"><?php foreach($payments as $p):?><option value="<?=(int)$p['id']?>" <?=(int)$p['id']===$prefPayment?'selected':''?>>#<?=(int)$p['id']?> · <?=e($p['paid_on'].' · '.estateMoney((int)$p['amount_cents']-(int)$p['allocated']))?> EUR verfügbar</option><?php endforeach?></select></label><label>Vertrag<?php estateOptions($lists['leases'],'lease_id','id',$prefLease,false);?></label><label>Monatsforderung (bei Kaution ohne)<select name="charge_id"><option value="0">Keine / Kaution</option><?php foreach($ledger as $c):?><option value="<?=(int)$c['id']?>" <?=(int)$c['id']===$prefCharge?'selected':''?>>#<?=(int)$c['id']?> · Vertrag #<?=(int)$c['lease_id']?> · <?=e($c['tenant_name'].' · '.substr($c['month'],0,7))?></option><?php endforeach?></select></label><label>Komponente<select name="component"><option value="rent">Kaltmiete</option><option value="operating">Betriebskosten-Vorauszahlung/Pauschale</option><option value="heating">Heizkosten-Vorauszahlung/Pauschale</option><option value="deposit">Kaution / Kautionsrückzahlung</option></select></label><label>Betrag mit Vorzeichen EUR<input name="amount" inputmode="decimal" required></label><label>Vorauszahlung zugeordnet ab (optional, sonst Mietmonat)<input name="allocation_from" type="date"></label><label>Vorauszahlung zugeordnet bis einschließlich (optional)<input name="allocation_to" type="date"></label><label><input name="confirm" type="checkbox" required> Vertrag, Komponente, Vorauszahlungszeitraum und tatsächliche Zahlung geprüft.</label><button>Zuordnung bestätigen</button></form><p>Für andere Forderungsmonate über <a href="?view=payment&amp;month=<?=e(substr(planDate($month,-1),0,7))?>">vorherigen Monat</a> oder <a href="?view=payment&amp;month=<?=e(substr((new DateTimeImmutable($month))->modify('+1 month')->format('Y-m-d'),0,7))?>">nächsten Monat</a> wechseln.</p></section>
<section class="card"><h2>Kautionen (separat von Miete/Einnahmen)</h2><?php foreach($deposits as $d):?><p>Vertrag #<?=(int)$d['id']?> · <?=e($d['name'])?> · vereinbart <?=e(estateMoney((int)$d['deposit_cents']))?> · erfasst <?=e(estateMoney((int)$d['paid']))?> EUR. Keine Aussage über rechtlich notwendige gesonderte Verwahrung/Verzinsung.</p><?php endforeach?></section><section class="card"><h2>Zuordnungshistorie</h2><?php foreach($allocations as $a):?><p>#<?=(int)$a['id']?> · Zahlung #<?=(int)$a['payment_id']?> · Vertrag #<?=(int)$a['lease_id']?> · <?=e($a['component'].' · '.estateMoney((int)$a['amount_cents']))?> EUR · <?=e($a['reason'])?></p><?php if(!$a['reversal_of']):?><form method="post"><?php gszFields('reverse');estateRequest();?><input type="hidden" name="allocation_id" value="<?=(int)$a['id']?>"><label>Korrekturgrund<input name="reason" maxlength="1000" required></label><button>Zuordnung durch Gegenzeile aufheben</button></form><?php endif?><?php endforeach?></section><?php endif?>
<?php if($view==='document'):?><section class="card"><h2>Privates Immobilienarchiv</h2><form method="post" enctype="multipart/form-data"><?php gszFields('upload');?><label>Gebäude<?php estateOptions($lists['buildings'],'building_id','name');?></label><label>Vertrag<?php estateOptions($lists['leases'],'lease_id','id');?></label><label>Unverändertes Original (PDF/JPEG/PNG/Text/CSV, max10MB)<input name="original" type="file" required></label><button>Immobilienoriginal archivieren</button></form><?php foreach($documents as $d):?><p><a href="estate_download.php?id=<?=(int)$d['id']?>"><?=e($d['original_name'])?></a> · <?=e($d['created_at'])?> UTC</p><?php endforeach?></section><?php endif?>
<?php if($history):?><section class="card"><h2>Änderungshistorie</h2><?php foreach($history as $h):?><details><summary><?=e($h['created_at'].' UTC · '.$h['action'])?></summary><pre style="white-space:pre-wrap;overflow-wrap:anywhere"><?=e($h['changes_json'])?></pre></details><?php endforeach?></section><?php endif?><?php endif?><?php gszPageEnd();?>
